using System;using System.Linq;using System.Reflection;using NUnit.Framework;using UnityEngine;using Object=UnityEngine.Object;
namespace CurtainCall.EscapeRoute.Tests{
[Category("EscapePursuerComplete")]public sealed class PursuerBossTests{
const BindingFlags Flags=BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic;static Type Boss=>AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType("CurtainCall.EscapeRoute.EscapePursuerBoss")).First(t=>t!=null);static object Call(string name,params object[] a)=>Boss.GetMethod(name,Flags).Invoke(null,a);
[Test]public void EightDistinctCutsExposeAttachedLimbsAndSlowMonotonically(){byte mask=0;float previous=1;for(int i=0;i<8;i++){Assert.That(Call("Exposed",mask,i),Is.True);if(i<4)Assert.That(Call("Exposed",mask,i+4),Is.False);mask|=(byte)(1<<i);Assert.That(Call("Exposed",mask,i),Is.False);Assert.That(Call("CutCount",mask),Is.EqualTo(i+1));float speed=(float)Call("MovementScale",mask,.07f);Assert.That(speed,Is.LessThan(previous));previous=speed;}Assert.That(mask,Is.EqualTo(255));Assert.That(previous,Is.GreaterThanOrEqualTo(.4f));}
[TestCase(0f,true)][TestCase(2f,false)]public void FastDiskSweepHitsOrMissesRotatedScaledPart(float offset,bool expected){var go=new GameObject("Cut geometry");try{go.transform.SetPositionAndRotation(new Vector3(9000,50,9000),Quaternion.Euler(0,47,0));go.transform.localScale=new Vector3(.5f,2,1);var b=go.AddComponent<BoxCollider>();object[] args={b,go.transform.TransformPoint(new Vector3(offset,0,-5)),go.transform.TransformPoint(new Vector3(offset,0,5)),Vector3.up,.3f,.12f,0f};Assert.That(Call("IntersectPart",args),Is.EqualTo(expected));}finally{Object.DestroyImmediate(go);}}
[Test]public void InvalidDiskDoesNotCut(){var go=new GameObject("Invalid disk");try{var b=go.AddComponent<BoxCollider>();object[] args={b,Vector3.back,Vector3.forward,Vector3.up,float.NaN,.1f,0f};Assert.That(Call("IntersectPart",args),Is.False);args[4]=.5f;args[3]=Vector3.zero;Assert.That(Call("IntersectPart",args),Is.False);}finally{Object.DestroyImmediate(go);}}
}}
